"""Builds web/kiri/lang/uk.js from the keys of en.js and tools/uk_strings.py: python3 -I tools/make_uk.py"""
import json, pathlib, re, sys
root = pathlib.Path(__file__).resolve().parent.parent
sys.path.insert(0, str(root / 'tools'))
from uk_strings import UK  # noqa: E402

en = (root / 'web/kiri/lang/en.js').read_text()
keys = re.findall(r'^    ([a-z0-9_]+):', en, re.M)
unknown = sorted(set(UK) - set(keys))
if unknown:
    sys.exit(f'keys not in en.js: {unknown}')
lines = [
    '// Ukrainian (EduProstir). Generated by tools/make_uk.py from tools/uk_strings.py: edit those, not this file.',
    '// Missing keys (CNC, laser, SLA, belt printers) fall back to English.',
    "self.lang['uk'] =",
    "self.lang['uk-ua'] = {",
]
seen = set()
for key in keys:
    if key in UK and key not in seen:
        seen.add(key)
        lines.append(f'    {key}: {json.dumps(UK[key], ensure_ascii=False)},')
lines.append('};')
(root / 'web/kiri/lang/uk.js').write_text('\n'.join(lines) + '\n')
print(f'uk.js: {len(seen)} of {len(set(keys))} keys')
